  const cz = Math.floor(z);
  if (cx < 0 || cz < 0 || cx >= worldSize || cz >= worldSize) return 'wall';
  return world[cx][cz];
}

function canMoveTo(x, z) {
  const cx = Math.floor(x);
  const cz = Math.floor(z);
  if (cx < 0 || cz < 0 || cx >= worldSize || cz >= worldSize) return false;
  if (world[cx][cz] !== null && world[cx][cz] !== 'water') return false;
  return true;
}

function tryMove(dx, dz) {
  const nextX = state.player.x + dx;
  const nextZ = state.player.z + dz;
  const step = 0.28;
  if (canMoveTo(nextX + step, nextZ + step) && canMoveTo(nextX - step, nextZ + step) && canMoveTo(nextX + step, nextZ - step) && canMoveTo(nextX - step, nextZ - step)) {
    state.player.x = clamp(nextX, 0.8, worldSize - 0.8);
    state.player.z = clamp(nextZ, 0.8, worldSize - 0.8);
  }
}

function pickupCrystals() {
  for (let i = crystals.length - 1; i >= 0; i--) {
    const crystal = crystals[i];
    const dx = crystal.x - state.player.x;
    const dz = crystal.z - state.player.z;
    if (Math.hypot(dx, dz) < 0.7 && crystal.active) {
      crystal.active = false;
      state.crystalCount += 1;
      if (state.crystalCount >= 8) {
        messageEl.textContent = 'Portal unlocked!';
      }
    }
  }
}

