  const dx = state.player.x - state.portal.x;
  const dz = state.player.z - state.portal.z;
  if (Math.hypot(dx, dz) < 0.8 && state.crystalCount >= 8) {
    state.won = true;
    messageEl.textContent = 'You won!';
  }
}

