function drawBackground() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  const sky = ctx.createLinearGradient(0, 0, 0, h);
  sky.addColorStop(0, '#75d0ff');
  sky.addColorStop(0.5, '#d7f2ff');
  sky.addColorStop(0.5, '#6bbd61');
  sky.addColorStop(1, '#2d593d');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, w, h);
}

function drawGrid() {
  const pad = 18;
  const cell = Math.min((window.innerWidth - pad * 2) / worldSize, (window.innerHeight - pad * 2) / worldSize);
  const offsetX = (window.innerWidth - cell * worldSize) / 2;
  const offsetY = (window.innerHeight - cell * worldSize) / 2;

  for (let x = 0; x < worldSize; x++) {
    for (let z = 0; z < worldSize; z++) {
      const px = offsetX + x * cell;
      const py = offsetY + z * cell;
      const type = world[x][z];
      if (!type) {
        ctx.fillStyle = '#95d98b';
        ctx.fillRect(px + 1, py + 1, cell - 2, cell - 2);
      } else {
        const block = blockTypes[type];
        ctx.fillStyle = block.color;
        ctx.fillRect(px + 1, py + 1, cell - 2, cell - 2);
        ctx.fillStyle = block.accent;
        ctx.fillRect(px + 3, py + 3, cell - 6, cell * 0.25);
      }
    }
  }

  const portalX = offsetX + state.portal.x * cell;
  const portalY = offsetY + state.portal.z * cell;
  ctx.fillStyle = '#d6f7ff';
  ctx.fillRect(portalX + cell * 0.2, portalY + cell * 0.2, cell * 0.6, cell * 0.6);
  ctx.fillStyle = state.crystalCount >= 8 ? '#7ef0d2' : '#5c6d85';
  ctx.fillRect(portalX + cell * 0.3, portalY + cell * 0.3, cell * 0.4, cell * 0.4);

  crystals.forEach((crystal) => {
    if (!crystal.active) return;
    const px = offsetX + crystal.x * cell;
    const py = offsetY + crystal.z * cell;
    const pulse = 0.7 + Math.sin(crystal.glow + performance.now() * 0.006) * 0.25;
    ctx.fillStyle = '#79f7eb';
    ctx.beginPath();
    ctx.arc(px + cell / 2, py + cell / 2, cell * 0.18 * pulse, 0, Math.PI * 2);
    ctx.fill();
  });

  const playerX = offsetX + state.player.x * cell;
  const playerY = offsetY + state.player.z * cell;
  ctx.fillStyle = '#ffcf5b';
  ctx.beginPath();
  ctx.arc(playerX + cell / 2, playerY + cell / 2, cell * 0.18, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#eb3b3b';
  ctx.fillRect(playerX + cell * 0.3, playerY + cell * 0.1, cell * 0.4, cell * 0.25);
}

